const { isE164 } = require('./validate');
const { normalize } = require('./normalize');

function queueText(outbox, rawTo, text) {
  const to = normalize(rawTo);
  if (!isE164(to)) throw new Error('bad number: ' + rawTo);
  outbox.push({ to, text: text.slice(0, 160) });
}

module.exports = { queueText };
